class Solution {
  public long elevatorRequests(int n, int start, int[][] requests) {
    int m = requests.length;
    long INF = Long.MAX_VALUE / 4;
    long[][] dp = new long[1 << m][m];
    for (long[] row : dp) java.util.Arrays.fill(row, INF);
    for (int j = 0; j < m; j++)
      dp[1 << j][j] = Math.max((long) Math.abs(start - requests[j][1]), requests[j][0]);
    long best = INF;
    for (int mask = 1; mask < (1 << m); mask++) {
      for (int last = 0; last < m; last++) {
        long cur = dp[mask][last];
        if (cur >= INF) continue;
        if (mask == (1 << m) - 1) best = Math.min(best, cur);
        for (int j = 0; j < m; j++) {
          if ((mask >> j & 1) != 0) continue;
          long t = Math.max(cur + Math.abs(requests[last][1] - requests[j][1]), requests[j][0]);
          int nm = mask | 1 << j;
          if (t < dp[nm][j]) dp[nm][j] = t;
        }
      }
    }
    return best;
  }
}
